import trebleUrl from "./art/treble-clay.webp?inline";
import bassUrl from "./art/bass-clay.webp?inline";

/** Embedded assets keep a serialized SVG self-contained when it is rasterized in the 3D world. */
export const CLAY_CLEF_URLS = { treble: trebleUrl, bass: bassUrl } as const;

/** Only our exact generated bytes with their matching marker may survive score export. */
export function isClayClefImage(image: Element): boolean {
  const kind = image.getAttribute("data-clay-clef-image");
  return (
    (kind === "treble" || kind === "bass") && image.getAttribute("href") === CLAY_CLEF_URLS[kind]
  );
}
